const inputItem = $input.first();
const raw = inputItem.json;
let text = '';

// Extract raw text from Gemini
if (raw.candidates && raw.candidates[0]?.content?.parts?.[0]?.text) {
  text = raw.candidates[0].content.parts[0].text;
} else if (raw.text) {
  text = raw.text;
} else if (typeof raw === 'string') {
  text = raw;
}

// 1. Sanitize text and remove multiple blank lines
let clean = text
  .replace(/\r\n/g, '\n')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

// 2. Extract Status for Badges
const isRejected = /Rejected/i.test(clean);
const isResubmit = /Revise\s*&\s*Resubmit/i.test(clean);
const statusColor = isRejected ? '#dc2626' : (isResubmit ? '#d97706' : '#16a34a');
const statusBg = isRejected ? '#fef2f2' : (isResubmit ? '#fffbeb' : '#f0fdf4');
const statusBorder = isRejected ? '#fecaca' : (isResubmit ? '#fde68a' : '#bbf7d0');

// 3. Ultra-compact HTML formatting (minimal margins, tight line-height)
let compactHtml = clean
  // Top Title Banner
  .replace(/# COMMERCIAL VARIATION REVIEW([\s\S]*?)(?=## 1\.|$)/i, (match) => {
    let details = match
      .replace(/# COMMERCIAL VARIATION REVIEW/i, '')
      .replace(/\*\*(.*?)\*\*:\s*([^\n<]+)/g, '<div style="margin-bottom: 2px;"><span style="color: #64748b; font-weight: 600;">$1:</span> <strong style="color: #0f172a;">$2</strong></div>')
      .trim();
    return `
      <div style="background: #f8fafc; border: 1px solid #e2e8f0; border-radius: 4px; padding: 8px 10px; margin-bottom: 8px;">
        <div style="display: flex; justify-content: space-between; align-items: center; border-bottom: 1px solid #e2e8f0; padding-bottom: 4px; margin-bottom: 6px;">
          <span style="font-weight: 800; font-size: 11.5px; color: #0f172a; text-transform: uppercase;">EXAMPLE DEVELOPER &bull; COMMERCIAL REVIEW</span>
          <span style="background: ${statusBg}; color: ${statusColor}; border: 1px solid ${statusBorder}; font-size: 10px; font-weight: 800; padding: 1px 6px; border-radius: 3px;">
            ${isRejected ? 'REJECTED' : (isResubmit ? 'REVISE & RESUBMIT' : 'RECOMMENDED FOR APPROVAL')}
          </span>
        </div>
        <div style="font-size: 11px; line-height: 1.35; display: grid; grid-template-columns: 1fr 1fr; gap: 2px 10px;">
          ${details}
        </div>
      </div>
    `;
  })

  // Section Headers (Ultra-tight margins)
  .replace(/## (\d+\.\s*[^<\n]+)/gi, `
    <div style="margin-top: 8px; margin-bottom: 4px; border-bottom: 1.5px solid #0f172a; padding-bottom: 2px;">
      <span style="font-size: 11.5px; font-weight: 800; color: #0f172a; text-transform: uppercase;">$1</span>
    </div>
  `)

  // Sub-headings (Proofs)
  .replace(/### (PROOF\s*\d+[^<\n]*)/gi, `
    <div style="background: #f1f5f9; border-left: 3px solid #0284c7; padding: 3px 6px; margin: 4px 0 2px 0; font-size: 11px; font-weight: 700; color: #0369a1;">
      📌 $1
    </div>
  `)

  // Verbatim Quotes (Single compact block)
  .replace(/^>\s*"?([\s\S]*?)"?$/gim, `
    <div style="background: #ffffff; border: 1px dashed #cbd5e1; border-left: 3px solid #d97706; padding: 5px 8px; margin: 3px 0 5px 0; font-family: Courier New, monospace; font-size: 10.5px; color: #1e293b; line-height: 1.3; border-radius: 0 3px 3px 0;">
      <span style="font-size: 9.5px; font-weight: bold; color: #d97706; text-transform: uppercase; display: block; margin-bottom: 1px;">Contract Verbatim:</span>
      "$1"
    </div>
  `)

  // Compact Bullet Points
  .replace(/^\s*-\s*\*\*(.*?)\*\*:\s*([^\n<]+)/gim, '<div style="font-size: 11px; line-height: 1.35; margin: 2px 0;"><strong style="color: #475569;">&bull; $1:</strong> <span style="color: #0f172a;">$2</span></div>')
  .replace(/^\s*-\s*([^\n<]+)/gim, '<div style="font-size: 11px; line-height: 1.35; margin: 2px 0; color: #334155;">&bull; $1</div>')

  // Bold Text
  .replace(/\*\*(.*?)\*\*/gim, '<strong>$1</strong>')

  // Collapse newlines
  .replace(/\n{2,}/g, '')
  .replace(/\n/g, '');

// Safe retrieval of Google Drive link
let webViewLink = 'https://drive.google.com';
try {
  webViewLink = $('Download file').first().json.webViewLink || webViewLink;
} catch (e) {}

// Collect and preserve all binary attachments from upstream nodes
let combinedBinary = {};

try {
  const gmailNode = $('Gmail Trigger').first();
  if (gmailNode && gmailNode.binary) {
    combinedBinary = { ...combinedBinary, ...gmailNode.binary };
  }
} catch (e) {}

try {
  const driveNode = $('Download file').first();
  if (driveNode && driveNode.binary) {
    combinedBinary = { ...combinedBinary, ...driveNode.binary };
  }
} catch (e) {}

if (inputItem && inputItem.binary) {
  combinedBinary = { ...combinedBinary, ...inputItem.binary };
}

const outputItem = {
  json: {
    report_html: compactHtml,
    contract_webViewLink: webViewLink,

    // Essential fields for downstream baseline/financials
    project_name: 'Sample Waterfront Development, Main Works Package',
    contractor_name: 'Example Contracting LLC',
    letter_ref: 'EXC-VX-0001',
    submittal_ref: 'EXC-VX-0001',
    contract_ref: 'EXD/CON/SAMPLE/001',
    contract_type: 'LUMPSUM',
    proposed_amount: -365000.00,
    variation_value: -365000.00,
    this_vo_amount: -365000.00,
    time_impact: 'No Time Impact',
    scope_summary: 'PC Rate Adjustment for Concrete & Reinforcement',
    ai_commercial_recommendation: isRejected ? 'Rejected' : (isResubmit ? 'Revise & Resubmit to Consultant' : 'Recommended for Approval'),
    ai_contractual_justification: 'Revise & Resubmit pending Annexure A evaluation and rate substantiation.'
  }
};

if (Object.keys(combinedBinary).length > 0) {
  outputItem.binary = combinedBinary;
}

return [outputItem];

const inputItem = $input.first();

// 1. Google Sheets Baseline Data
let sheetData = {};
try {
  sheetData = $('Contract Baseline').first().json || {};
} catch (e) {
  try {
    sheetData = $('Get Contract Baseline').first().json || {};
  } catch (err) {
    sheetData = {};
  }
}

// 2. Parsed Input & Upstream Data
let item = {};
try {
  item = $('Format Variation Input').first().json || inputItem.json || {};
} catch (e) {
  item = inputItem.json || {};
}

// 3. Extract Raw AI Document Analysis Output
let aiFullAnalysis = '';
try {
  const aiNode = $('Analyze document').first().json;
  aiFullAnalysis = aiNode.text || aiNode.output || (aiNode.content && aiNode.content.parts && aiNode.content.parts[0].text) || '';
} catch (e) {
  aiFullAnalysis = '';
}

// 4. Extract Original Contractor Letter Body
let originalLetterText = '';
try {
  const gmailNode = $('Gmail Trigger').first().json;
  originalLetterText = gmailNode.snippet || gmailNode.textPlain || gmailNode.text || '';
} catch (e) {
  originalLetterText = '';
}

// 5. Numeric Parser
const num = (v) => {
  if (typeof v === 'number') return v;
  if (!v) return 0;
  return parseFloat(String(v).replace(/[^0-9.-]/g, '')) || 0;
};

// 6. Currency Formatter
const formatAED = (val, encloseNegative = false) => {
  const isNeg = val < 0;
  const formatted = Math.abs(val).toLocaleString('en-US', {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2
  });
  if (isNeg && encloseNegative) {
    return `(AED ${formatted})`;
  }
  return isNeg ? `-AED ${formatted}` : `AED ${formatted}`;
};

// 7. Contract & Variation Financials
const originalContractSum = num(sheetData['Original Contract Sum (AED)'] || sheetData.original_contract_sum || item.original_contract_sum || 3260000.00);
const previousVariations = num(sheetData['Previous Variations (AED)'] || sheetData.previous_variations_total || item.previous_variations_total || 285000.00);
const thisVoAmount = num(item.proposed_amount !== undefined && item.proposed_amount !== 0 ? item.proposed_amount : (item.this_vo_amount || -365000.00));

const subTotalBeforeThisVO = originalContractSum + previousVariations;
const revisedContractSum = subTotalBeforeThisVO + thisVoAmount;

// 8. Project Master Budget Level Reconciliations
const approvedBudgetValue = num(sheetData['Approved Budget Value'] || sheetData.approved_budget_value || item.approved_budget_value || 50150000.00);
const sapWbsCode = sheetData['SAP Budget Code'] || sheetData.sap_wbs_code || item.sap_wbs_code || 'RAH21/01-CC-INFRA';
const contractClauseRef = sheetData.contract_clause_ref || item.contract_clause_ref || 'Clause-I of Contract Agreement & Schedule (D)';
const committedPreVO = num(sheetData.committed_amount_pre_vo || item.committed_amount_pre_vo || (approvedBudgetValue - 48000000.00));

const balanceBudgetPreVO = approvedBudgetValue - committedPreVO;
const revisedCommittedPostVO = committedPreVO + thisVoAmount;
const balanceBudgetPostVO = approvedBudgetValue - revisedCommittedPostVO;

// 9. Structured AI & Contract Audit Content
const scopeSummary = item.scope_summary || item.scope_description || 'PC Rate Adjustment for Concrete & Reinforcement';
const timeImpact = item.time_impact || 'No Time Impact (0 Days EOT)';
const contractualJustification = item.ai_contractual_justification || 'Revise & Resubmit pending Annexure A evaluation and rate substantiation under Clause-I & Schedule D.';
const commercialRecommendation = item.ai_commercial_recommendation || 'Revise & Resubmit to Consultant';

const finalAiClauseExplanation = item.report_html || aiFullAnalysis || `• Contractual Entitlement: Evaluated under ${contractClauseRef}. The requested rate adjustment requires reconciliation against baseline Schedule D bill of quantities.
• Scope Verification: Technical review confirms concrete and reinforcement quantity adjustments matching site instruction records.
• Rate Substantiation: Supporting invoices and market rate documentation for Annexure A are currently incomplete.
• Clause Compliance: Submittal complied with notice requirements, but pricing verification remains conditional upon consultant rate re-audit.`;

const finalLetterContent = originalLetterText || `Reference: EXC-VX-0001
Project: Sample Waterfront Development, Main Works Package
Subject: Variation Claim No. 02 - PC Rate Adjustment for Concrete & Reinforcement

We hereby submit our commercial variation claim for the adjustment of prime cost rates concerning structural concrete and high-tensile reinforcement bar works. The total adjusted value amounts to AED -365,000.00 (Credit) with zero schedule extension. Relevant backup measurements are submitted herewith for commercial review and certification.`;

// 10. Forward all binary attachments
let forwardBinary = {};
try {
  if (inputItem && inputItem.binary) {
    forwardBinary = { ...forwardBinary, ...inputItem.binary };
  }
} catch (e) {}

try {
  const prevFormat = $('Format Variation Input').first();
  if (prevFormat && prevFormat.binary) {
    forwardBinary = { ...forwardBinary, ...prevFormat.binary };
  }
} catch (e) {}

const outputItem = {
  json: {
    ...item,
    ...sheetData,
    original_letter_received: finalLetterContent,
    ai_full_clause_explanation: finalAiClauseExplanation,
    project_name: sheetData['Project Name'] || sheetData.project_name || item.project_name || 'Sample Waterfront Development, Main Works Package',
    contractor_name: sheetData['Contractor Name'] || sheetData.contractor_name || 'Example Contracting LLC',
    sap_wbs_code: sapWbsCode,
    contract_clause_ref: contractClauseRef,
    ai_audit: {
      scope: scopeSummary,
      time_impact: timeImpact,
      clause_justification: contractualJustification,
      recommendation: commercialRecommendation
    },
    calc: {
      original_contract_sum: originalContractSum,
      previous_variations: previousVariations,
      this_vo_amount: thisVoAmount,
      sub_total_before_this_vo: subTotalBeforeThisVO,
      revised_contract_sum: revisedContractSum,
      approved_budget_value: approvedBudgetValue,
      committed_pre_vo: committedPreVO,
      balance_budget_pre_vo: balanceBudgetPreVO,
      balance_budget_post_vo: balanceBudgetPostVO
    },
    display: {
      original_contract_sum: formatAED(originalContractSum),
      previous_variations: formatAED(previousVariations),
      this_vo_amount: formatAED(thisVoAmount, true),
      sub_total_before_this_vo: formatAED(subTotalBeforeThisVO),
      revised_contract_sum: formatAED(revisedContractSum),
      approved_budget_value: formatAED(approvedBudgetValue),
      committed_pre_vo: formatAED(committedPreVO),
      balance_budget_pre_vo: formatAED(balanceBudgetPreVO),
      balance_budget_post_vo: formatAED(balanceBudgetPostVO),
      is_negative_vo: thisVoAmount < 0
    }
  }
};

if (Object.keys(forwardBinary).length > 0) {
  outputItem.binary = forwardBinary;
}

return [outputItem];

