// Upstream data from Calculate VO Financials
const voData = $('Calculate VO Financials').first()?.json || {};

// Safely check if Google Drive has run yet
let driveFolderLink = '#';
try {
  driveFolderLink = $('Upload VO to Google Drive').first()?.json?.webViewLink || '#';
} catch (e) {
  driveFolderLink = '#';
}

const originalDocs = {
  contractorLetterRef: voData.letter_ref || 'EXC-VX-0001',
  submissionDate: voData.date || new Date().toISOString().split('T')[0],
  driveFolderLink: driveFolderLink,
  summary: voData.summary || 'Variation Order Submittal & PC Rate Adjustment'
};

// Safe approval tracking
let avpJustification = 'Pending initial review';
try {
  avpJustification = $('Wait for Commercial Approval').first()?.json?.['Commercial Narrative & Justification'] || avpJustification;
} catch (e) {}

let pmComments = 'Awaiting PM review';
try {
  pmComments = $('Wait for SPM Approval').first()?.json?.['comments'] || pmComments;
} catch (e) {}

const approvals = {
  avpCommercial: {
    name: 'AVP Commercial',
    status: avpJustification !== 'Pending initial review' ? 'Approved' : 'Pending',
    date: new Date().toLocaleDateString('en-GB'),
    comments: avpJustification
  },
  srPM: {
    name: 'Sr. Project Manager',
    status: pmComments !== 'Awaiting PM review' ? 'Approved' : 'Pending',
    date: '-',
    comments: pmComments
  }
};

// Safely capture incoming binary file from upstream nodes
let binaryData = {};

try {
  binaryData = $('Analyze document').first()?.binary || {};
} catch (e) {}

if (!binaryData || Object.keys(binaryData).length === 0) {
  try {
    binaryData = $('Merge').first()?.binary || {};
  } catch (e) {}
}

if (!binaryData || Object.keys(binaryData).length === 0) {
  try {
    binaryData = $('Download file').first()?.binary || {};
  } catch (e) {}
}

if (!binaryData || Object.keys(binaryData).length === 0) {
  try {
    binaryData = $('Gmail Trigger').first()?.binary || {};
  } catch (e) {}
}

if (!binaryData || Object.keys(binaryData).length === 0) {
  try {
    binaryData = $input.first()?.binary || {};
  } catch (e) {}
}

// Ensure the binary object contains 'attachment_1' and 'attachment_0' for the Gmail node
const finalBinary = { ...binaryData };

// Specifically target contract PDF if available
const contractPdfKey = Object.keys(binaryData).find(key => key.includes('contract') || key === 'attachment_1' || key === 'attachment_0');

if (contractPdfKey && !finalBinary['attachment_1']) {
  finalBinary['attachment_1'] = binaryData[contractPdfKey];
}

// Ensure attachment_0 is also populated as a fallback or logo
if (!finalBinary['attachment_0'] && contractPdfKey) {
  finalBinary['attachment_0'] = binaryData[contractPdfKey];
}

// Return JSON combined with the binary stream
return [{
  json: {
    ...voData,
    originalDocs,
    approvals
  },
  binary: finalBinary
}];
